begin;
do $test$
declare actor uuid; leader uuid; worker uuid; a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();semi uuid:=gen_random_uuid();station text:='MPLAN-'||substr(gen_random_uuid()::text,1,8);dep text;shift_id uuid:=gen_random_uuid();schedule_id uuid:=gen_random_uuid();payload jsonb;result jsonb;run_a public.production_live_runs;run_b public.production_live_runs;v timestamptz;request uuid:=gen_random_uuid();target_before numeric;qty_before bigint;
begin
 dep:=station||'-DEP';
 select a.user_id into actor from public.global_system_admins a join public.operadores o on o.uid=a.user_id where o.activo limit 1;
 select m.user_id into leader from public.global_department_memberships m join public.operadores o on o.uid=m.user_id join public.global_role_access_profiles p on p.department=m.department and p.role=m.role where m.department='production' and m.active and m.role in('lider','supervisor') and o.activo and 'shifts'=any(p.activities) limit 1;
 select m.user_id into worker from public.global_department_memberships m join public.operadores o on o.uid=m.user_id where m.department='production' and m.active and m.role='operador' and o.activo limit 1;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 insert into public.inventory_items(id,part_number,category) values(a,'MPLAN-A-'||a,'FG'),(b,'MPLAN-B-'||b,'FG'),(semi,'MPLAN-S-'||semi,'SEMI');
 insert into public.inventory_workstations(code,name,machine_type,materials) values(station,'Main plan test',(select name from public.machine_types limit 1),jsonb_build_array(jsonb_build_object('item_ids',jsonb_build_array(a,b)))),(dep,'Dependency plan test',(select name from public.machine_types limit 1),jsonb_build_array(jsonb_build_object('item_ids',jsonb_build_array(semi))));
 perform public.production_machine_bom_action('save',jsonb_build_object('root_station_code',station,'dependency_station_code',dep,'item_ids',jsonb_build_array(semi),'enabled',true));
 if not exists(select 1 from public.inventory_machine_bom_links where root_station_code=station and dependency_station_code=dep and item_ids=array[semi]) then raise exception 'link not saved';end if;
 select updated_at into v from public.inventory_machine_bom_links where root_station_code=station and dependency_station_code=dep;
 begin perform public.production_machine_bom_action('save',jsonb_build_object('root_station_code',station,'dependency_station_code',dep,'item_ids',jsonb_build_array(a),'enabled',true,'version',v));raise exception 'wrong producer accepted';exception when others then if sqlerrm<>'pr_output_required' then raise;end if;end;
 perform public.production_machine_bom_action('save',jsonb_build_object('root_station_code',station,'dependency_station_code',dep,'item_ids',jsonb_build_array(semi),'enabled',false,'version',v));
 select updated_at into v from public.inventory_machine_bom_links where root_station_code=station and dependency_station_code=dep;
 perform public.production_machine_bom_action('delete',jsonb_build_object('root_station_code',station,'dependency_station_code',dep,'version',v));
 if exists(select 1 from public.inventory_machine_bom_links where root_station_code=station and dependency_station_code=dep) then raise exception 'restore/delete failed';end if;
 payload:=jsonb_build_object('id',shift_id,'started_at',clock_timestamp()-interval '1 hour','shift_hours',8,'planned_hours',8,'stations',jsonb_build_array(jsonb_build_object('station_code',station,'item_ids',jsonb_build_array(a,b),'planned_hours',4,'product_hours',jsonb_build_object(a::text,4,b::text,6))));
 perform public.production_shift_plan(payload);perform public.production_shift_plan(payload);
 select * into run_a from public.production_live_runs where station_code=station and item_id=a;select * into run_b from public.production_live_runs where station_code=station and item_id=b;
 if run_a.planned_hours<>4 or run_b.planned_hours<>6 or run_a.shift_hours<>8 or (select count(*) from public.production_live_runs where station_code=station)<>2 then raise exception 'product duration/start retry failed';end if;
 target_before:=run_a.shift_target;qty_before:=run_a.latest_quantity;
 perform set_config('request.jwt.claim.sub',coalesce(leader,actor)::text,true);
 payload:=jsonb_build_object('id',request,'products',jsonb_build_array(jsonb_build_object('run_id',run_a.id,'version',coalesce(run_a.updated_at,run_a.created_at),'planned_hours',5)));
 perform public.production_update_run_plan(payload);perform public.production_update_run_plan(payload);
 if not exists(select 1 from public.production_live_runs where id=run_a.id and planned_hours=5 and shift_hours=8 and shift_target is not distinct from target_before and latest_quantity=qty_before and started_at=run_a.started_at) then raise exception 'plan edit changed reference/actuals';end if;
 begin perform public.production_update_run_plan(jsonb_build_object('id',gen_random_uuid(),'products',jsonb_build_array(jsonb_build_object('run_id',run_a.id,'version',coalesce(run_a.updated_at,run_a.created_at),'planned_hours',7))));raise exception 'stale accepted';exception when others then if sqlerrm<>'mp_changed' then raise;end if;end;
 select * into run_a from public.production_live_runs where id=run_a.id;
 perform public.production_update_run_plan(jsonb_build_object('id',gen_random_uuid(),'products',jsonb_build_array(jsonb_build_object('run_id',run_a.id,'version',run_a.updated_at,'planned_hours',7),jsonb_build_object('run_id',run_b.id,'version',coalesce(run_b.updated_at,run_b.created_at),'planned_hours',7))));
 if exists(select 1 from public.production_live_runs where station_code=station and planned_hours<>7) then raise exception 'whole machine duration edit failed';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 perform public.production_shift_plan(jsonb_build_object('id',schedule_id,'started_at',clock_timestamp()+interval '2 days','shift_hours',10,'planned_hours',10,'stations',jsonb_build_array(jsonb_build_object('station_code',station,'item_ids',jsonb_build_array(a,b),'planned_hours',4,'product_hours',jsonb_build_object(a::text,4,b::text,6)))));
 if not exists(select 1 from public.production_shift_schedule sc where sc.payload->'stations'->0->>'station_code'=station and sc.status='scheduled' and (sc.payload->>'planned_hours')::numeric=6 and (sc.payload->'stations'->0->'product_hours'->>a::text)::numeric=4 and (sc.payload->'stations'->0->'product_hours'->>b::text)::numeric=6) then raise exception 'schedule lost product durations/max';end if;
 perform set_config('request.jwt.claim.sub',worker::text,true);
 result:=public.production_machine_bom_snapshot();if result->'stations' is null then raise exception 'worker cannot read dependencies';end if;
 begin perform public.production_update_run_plan(jsonb_build_object('id',gen_random_uuid(),'products',jsonb_build_array(jsonb_build_object('run_id',run_a.id,'version',run_a.updated_at,'planned_hours',4))));raise exception 'worker edited plan';exception when others then if sqlerrm<>'pr_forbidden' then raise;end if;end;
 begin perform public.production_machine_bom_action('save',jsonb_build_object('root_station_code',station,'dependency_station_code',dep,'item_ids',jsonb_build_array(semi),'enabled',true));raise exception 'worker edited machine BOM';exception when others then if sqlerrm<>'pr_forbidden' then raise;end if;end;
end $test$;
rollback;
